 "content": "from collections import deque


def transform(grid):
    """Extend non-5 color motifs along adjacent straight 5-lines."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    original = [row[:] for row in grid]
    seen = set()

    # Connected non-background, non-guide components are candidate motifs.
    components = []
    for r in range(h):
        for c in range(w):
            if original[r][c] in (0, 5) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x, original[y][x]))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            original[ny][nx] not in (0, 5) and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            components.append(comp)

    # Find maximal horizontal and vertical guide runs. For each neighboring
    # motif, repeat its slices along the run, phased from the motif's first
    # coordinate on the run axis.
    segments = []
    for r in range(h):
        c = 0
        while c < w:
            if original[r][c] != 5:
                c += 1
                continue
            start = c
            while c < w and original[r][c] == 5:
                c += 1
            if c - start >= 2:
                segments.append(("h", r, start, c - 1))
    for c in range(w):
        r = 0
        while r < h:
            if original[r][c] != 5:
                r += 1
                continue
            start = r
            while r < h and original[r][c] == 5:
                r += 1
            if r - start >= 2:
                segments.append(("v", c, start, r - 1))

    for orient, fixed, lo, hi in segments:
        for comp in components:
            # A candidate component must touch this run from one of its sides.
            touches = []
            for y, x, _ in comp:
                if orient == "h":
                    if y in (fixed - 1, fixed + 1) and lo <= x <= hi:
                        if original[y][x] != 5:
                            touches.append(x)
                else:
                    if x in (fixed - 1, fixed + 1) and lo <= y <= hi:
                        if original[y][x] != 5:
                            touches.append(y)
            if not touches:
                continue

            axis_coords = [x if orient == "h" else y for y, x, _ in comp]
            anchor = min(axis_coords)
            period = max(axis_coords) - anchor + 1
            if period <= 0:
                continue

            # For every guide coordinate, stamp the source motif's matching
            # periodic slice. The perpendicular coordinates remain unchanged.
            for t in range(lo, hi + 1):
                phase = (t - anchor) % period
                for y, x, color in comp:
                    a = x if orient == "h" else y
                    if (a - anchor) % period != phase:
                        continue
                    ny, nx = (y, t) if orient == "h" else (t, x)
                    if 0 <= ny < h and 0 <= nx < w and original[ny][nx] == 0:
                        out[ny][nx] = color
    return out
